 qp=ROOT/'work/sprite_consistency_20261105/coverage/ver_buki_riko/x_animations.json';meta=json.loads(qp.read_text('utf8'));seqs=[s for s in meta['animations']if s['id']in (3,40)];need(len(seqs)==2,'Missing return table');need(digest(SOURCE)==SOURCE_SHA,'Wrong EXE source');files,_=read_disc(SOURCE,('SLUS_005.61',));exe=files['SLUS_005.61'];load=struct.unpack_from('<I',exe,0x18)[0];at=lambda x:int(x,16)-load+0x800;checks=[]
